/* v3.1 authority: static replay of executed MuJoCo reference artifacts. No browser ML backend. */
const ENGINEERING_DIR='idea-v3-2026-10-05/';
const ENGINEERING_DOCS={product:'01-idea-va-pitch.md',learning:'02-kien-truc-va-cach-hoc.md',business:'06-chi-phi-va-kha-thi.md',roadmap:'08-ke-hoach-trien-khai.md',sources:'03-workflow-du-lieu.md',architecture:'11-contracts-va-logic.md',validation:'05-thiet-ke-kiem-chung.md',outcomes:'18-ket-qua-ky-vong.md'};
function engineeringScope(){return `<div class="eng-scope"><span class="eng-pill executed">Reference MuJoCo đã chạy</span><span class="eng-pill pending">Native GR00T / GR1 chưa thử</span><span class="eng-pill pending">Human transfer / saving chưa chứng minh</span></div>`;}
function engineeringOverview(){return head('IDEA & EXAMPLE THỰC THI','Từ dữ liệu tới kỹ năng.<br>Kiểm từng bước bằng bằng chứng.','Phát triển một kỹ năng robot từ pretrained VLA, kiểm vai trò human và synthetic, rồi đo chất lượng và tổng chi phí. Đã có reference pipeline chạy thật để kiểm logic; native VLA cần tích hợp riêng.')+engineeringScope()+
 `<section class="panel eng-thesis"><h2>Một pipeline, ba ranh giới rõ</h2><div class="eng-columns"><div><strong>Dữ liệu → học</strong><p>Nhãn đúng, split đúng, loss và modules cập nhật đúng. Human bridge được chọn sau compatibility.</p></div><div><strong>Policy → robot</strong><p>Input, action, command và response có profile/timing. Scorer độc lập ghi cả unknown và chưa thử.</p></div><div><strong>Lỗi → can thiệp → đo lại</strong><p>Kỹ sư chọn phép thử/correction. Local gain chưa đủ; full-task/regression phải đạt theo tiêu chuẩn đã khóa.</p></div></div></section>`+
 `<section class="panel eng-architecture"><div class="eng-section-heading"><div><span class="eyebrow">KIẾN TRÚC & MỨC BẰNG CHỨNG</span><h2>Thiết kế native và phần đã thực thi</h2></div><a href="assets/kien-truc-v3.svg" target="_blank" rel="noopener">Mở sơ đồ đầy đủ ↗</a></div><img src="assets/kien-truc-v3.png" alt="Kiến trúc native và reference pipeline đã thực thi, có chỉ rõ human bridge và native VLA chưa tích hợp" width="1440" height="1300"></section>`+
 engineeringNativeWalkthrough()+`<details class="eng-reference-details"><summary>Phụ lục kỹ thuật: pipeline MuJoCo nhỏ đã chạy, có code và artifacts</summary>${engineeringExampleMarkup()}</details>`+`<section class="panel spaced"><h2>Điều kiện để gọi native VLA đã chạy</h2><p>Code/checkpoint pin, GR1 binding, native batch/loss/gradient/reload, learned closed-loop, native source adapters và độc lập final. Reference state adapter và predictor 4D không thay các bằng chứng này.</p><div class="eng-links"><a class="button" href="#learning">Cách học và gradient routes →</a><a class="button secondary" href="#resources">Đọc hồ sơ đầy đủ →</a><a href="assets/idea-v3.1.zip" download>Tải folder + code + artifacts ↓</a></div></section>`;}
function engineeringExampleMarkup(){return `<section id="engineering-example" class="panel eng-example"><div class="eng-section-heading"><div><span class="eyebrow">PHÉP THỬ PIPELINE THU NHỎ · BẢN CHẠY ĐÃ GHI</span><h2>Mô phỏng nhỏ để kiểm contracts</h2><p>Seed → QA → học → rollout → evidence → S/C alternatives → final/gate.</p></div><a href="data/engineering/report.json" target="_blank" rel="noopener">Report đo được ↗</a></div>
 <p class="eng-boundary">MuJoCo nhỏ · state idealized · sequencer scripted · action predictor học thật · grasp bằng weld. Đây là reference engineering, chưa VLM/GR1 hoặc human data.</p>
 <div class="eng-flow" role="group" aria-label="Các bước pipeline">${['Seed & QA','Học baseline','Chạy & gặp lỗi','Xem bằng chứng','Synthetic / correction','Final & gate'].map((s,i)=>`<button type="button" data-eng-step="${i}" aria-pressed="${i===0}"><span>${i+1}</span>${s}</button>`).join('')}</div>
 <div id="eng-workflow" class="eng-workflow" aria-live="polite"><p>Đang tải artifacts đã ghi…</p></div>
 <div class="eng-runtime"><div><label for="eng-case">Bản chạy để xem</label><select id="eng-case"><option value="R">R · một seed · lỗi trên vị trí mới</option><option value="S">S · thêm sim execution · hoàn thành reference</option><option value="C">C · model thu nhỏ học thêm correction</option><option value="binding">Lỗi binding · command lệch prediction</option><option value="unknown">Thiếu sensor của verifier · unknown</option><option value="zero">Chưa basic skill · fail bước đầu</option></select><div id="eng-scene" class="eng-scene" aria-label="Sơ đồ theo measured positions của bản ghi"></div><div class="eng-controls"><button type="button" id="eng-play" disabled aria-pressed="false">▶ Phát bản ghi</button><button type="button" id="eng-end" disabled>Xem bước cuối</button><output id="eng-position">—</output></div><label class="eng-sr" for="eng-frame">Bước thời gian trong bản ghi</label><input id="eng-frame" type="range" min="0" max="0" value="0" disabled><p class="small">Sơ đồ dựng từ measured simulator positions; không camera input hay robot video. Phát bản ghi không chạy training/backend trong browser.</p></div><div class="eng-evidence"><h3>Prediction → command → response</h3><div id="eng-values"></div><div id="eng-stages" class="eng-stages"></div><details><summary>Raw step và feature vector thực</summary><pre id="eng-raw"></pre></details></div></div>
 <div id="eng-summary" class="eng-summary"></div><p id="eng-load-status" class="small" role="status"></p><div class="eng-links"><a href="data/engineering/manifest.json" target="_blank" rel="noopener">Manifest / hashes ↗</a><a href="data/engineering/validation.json" target="_blank" rel="noopener">Kết quả tests thực ↗</a><a href="assets/idea-v3.1.zip" download>Code để chạy lại ↓</a></div></section>`;}
function renderEngineeringPage(id){
 const current=renderCurrentPlatform(id);if(current)return current;
 if(id==='engine')return renderModelEngineCore();
 if(id==='architecture')return renderDataFlywheel();
 if(id==='learning')return renderLearningCore();
 if(id==='sources')return renderDatasetBlueprint();
 if(id==='overview')return renderFlywheelOverview();
 if(id==='resources')return renderResourceHub();
 if(id==='research')return renderTrainingSurvey();
 if(id==='examples')return renderExampleNarrative();
 const file=ENGINEERING_DOCS[id];
 if(file){const d=DOSSIER.find(d=>d.path===ENGINEERING_DIR+file);return renderPitchPage(id,d);}
 return pages[id]();
}
function engScene(t){const o=t.measured,xy=v=>[55+(v[0]+.35)/.7*480,345-(v[1]+.27)/.54*280];const ee=xy(o.ee),ob=xy(o.object),tar=xy(o.target);return `<svg viewBox="0 0 630 400" role="img" aria-label="Vị trí robot, linh kiện và A1 đo được ở bước ${t.step}"><rect width="630" height="400" rx="16" fill="#edf3fa"/><rect x="35" y="45" width="520" height="320" rx="12" fill="#fff" stroke="#b9c9da"/>${[0,1,2,3,4].map(i=>`<path d="M${55+i*120} 60V345 M55 ${65+i*70}H535" stroke="#e2eaf3"/>`).join('')}<text x="50" y="30" fill="#425b77" font-size="14">Nhìn từ trên · measured positions</text><rect x="${tar[0]-22}" y="${tar[1]-22}" width="44" height="44" rx="7" fill="#ecfdf5" stroke="#168768" stroke-width="2"/><text x="${tar[0]-9}" y="${tar[1]+5}" fill="#147157" font-size="13">A1</text><rect x="${ob[0]-10}" y="${ob[1]-10}" width="20" height="20" rx="3" fill="#eab308" stroke="#8c6c04"/><path d="M40 350 L${ee[0]} ${ee[1]}" stroke="#a5bfde" stroke-width="7"/><circle cx="${ee[0]}" cy="${ee[1]}" r="${o.grip_closed?9:14}" fill="${o.attached_sensor?'#1d9c86':'#2563eb'}" fill-opacity=".7" stroke="#16355c" stroke-width="2"/><text x="565" y="55" fill="#425b77" font-size="12">z (m)</text><rect x="580" y="75" width="12" height="240" rx="4" fill="#dce6f1"/><circle cx="586" cy="${315-o.ee[2]/.3*240}" r="8" fill="#2563eb"/><rect x="578" y="${311-o.object[2]/.3*240}" width="16" height="8" fill="#eab308"/><text x="565" y="340" fill="#425b77" font-size="12">0 → 0.3</text><text x="50" y="389" fill="#425b77" font-size="13">Xanh: effector · Vàng: vật · A1: đích · Cột: độ cao</text></svg>`;}
async function initEngineering(signal){initNativeWalkthrough(signal);const root=document.querySelector('#engineering-example');if(!root)return;
 let timer=null,playing=false,index=0,step=0,kind='R',bundle;
 const play=root.querySelector('#eng-play'),range=root.querySelector('#eng-frame');
 const labels={approach:'Tiếp cận',grasp:'Gắp',lift:'Nâng',transfer:'Chuyển',place:'Đặt',release:'Nhả',retreat:'Rút'};
 function stop(){clearTimeout(timer);timer=null;playing=false;play.textContent='▶ Phát bản ghi';play.setAttribute('aria-pressed','false');}
 signal.addEventListener('abort',stop,{once:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();},{signal});
 try{
 const names=['report','before','after-synthetic','after-correction','binding-fault','unknown','zero-skill','validation'];
 const data=await Promise.all(names.map(async name=>{const res=await fetch('data/engineering/'+name+'.json',{signal});if(!res.ok)throw Error(name+' '+res.status);return res.json();}));if(signal.aborted)return;
 bundle={report:data[0],cases:{R:data[1],S:data[2],C:data[3],binding:data[4],unknown:data[5],zero:data[6]},validation:data[7]};
 const r=bundle.report,fmt=v=>Number(v).toFixed(4),counts=v=>`${v.successes}/${v.trials}`;
 function summary(){root.querySelector('#eng-summary').innerHTML=`<h3>Kết quả của run · không loại lượt thất bại</h3>${table(['Candidate','Development','Final giữ riêng','Regression','Gate reference'],['R','S','C'].map(k=>[k,r.development[k].success?'Pass':'Fail',counts(r.final[k]),r.regression[k].success?'Pass':'Fail',k==='S'&&r.promotion.reference_S?'Đạt trong reference':'Không promote']))}<p><strong>Kết quả C chỉ thuộc phép thử model thu nhỏ.</strong> Không kết luận phải thêm correction sau S hoặc cố dùng mọi nguồn. Native VLA / robot thật: chưa promote. Monetary saving: chưa chứng minh.</p>`;}
 function workflow(){let s;switch(step){
 case 0:s=`<h3>1 · Seed được thực thi, rồi kiểm release</h3><p>Một expert seed recording trong MuJoCo. Root và action profile4D khai rõ; dt0.05s, world meters. Human/RGB thiếu target không vào robot BC.</p><p>${r.generation.accepted} variants là descendants của <strong>1 seed root</strong>, không ${r.generation.accepted} robot demonstrations độc lập.</p><p>${bundle.validation.passed} tests passed: contracts, scoring, heldout, reload và promotion; không native tests.</p>`;break;
 case 1:s=`<h3>2 · Action predictor học thật, checkpoint có weights</h3>${table(['Run','Rows','Recordings / independent roots','MSE','Reload error'],['R','S','C'].map(k=>{const v=r.training[k];return[k,v.rows,`${v.recordings} / ${v.independent_roots}`,Number(v.loss).toExponential(2),Number(v.reload_max_error).toExponential(1)];}))}<p>35×4 linear weights được fit bằng ridge MSE trên absolute xyz/grip targets. Encoder state idealized và sequencer scripted. Chưa flow matching/VLM hoặc learned language grounding.</p>`;break;
 case 2:s='<h3>3 · Chạy closed-loop ở vị trí mới</h3><p>R fit từ một scene. Vật/đích đổi trong development làm policy thất bại tiếp cận; bước chưa tới là not_attempted. Chọn R, phát hoặc kéo timeline để xem predicted/sent/measured.</p>';break;
 case 3:s=`<h3>4 · Facts và hypothesis tách riêng</h3><p><strong>Observed:</strong> ${esc(r.evidence_card.observed)}.</p><p><strong>Hypothesis:</strong> ${esc(r.evidence_card.hypothesis)}.</p><p>So cùng scene/profile/scorer; kiểm riêng binding fault. Numeric features là adapter reference, chưa chứng minh model hiểu vật hoặc module native nào sai.</p>`;break;
 case 4:s='<h3>5 · Hai can thiệp thay thế, giữ seed replay</h3><p><strong>S:</strong> offset waypoint seed theo object/target frame, chạy 24 variants trong MuJoCo, QA positive, train với seed cũ.</p><p><strong>C:</strong> expert-reset correction trên development, train với seed cũ. Đây là alternative từ R, không tự thêm correction sau S đã tốt. Human branch chưa integrated.</p>';break;
 default:s='<h3>6 · Freeze rồi final; local gain chưa đủ</h3><p>12 scenarios mới chỉ được tạo/evaluate sau khi checkpoints và recipes đã khóa. Không dùng final để correction. S pass trong reference; C trong model thu nhỏ sửa scene development nhưng chưa đạt scene giữ riêng; không chọn candidate reference đó. Điều này không đánh giá correction trên native VLA. Không nhận GR1/human/savings từ kết quả này.</p>';
 }
 root.querySelector('#eng-workflow').innerHTML=s;root.querySelectorAll('[data-eng-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.engStep)===step)));}
 function render(){const ep=bundle.cases[kind];index=Math.min(index,ep.trace.length-1);const t=ep.trace[index];range.max=String(ep.trace.length-1);range.value=String(index);root.querySelector('#eng-scene').innerHTML=engScene(t);root.querySelector('#eng-position').textContent=`Bước ${index+1}/${ep.trace.length} · ${t.t.toFixed(2)}s`;
 root.querySelector('#eng-values').innerHTML=`<p><strong>Policy stage:</strong> ${labels[t.policy_stage]||esc(t.policy_stage)} · grip ${t.measured.grip_closed?'closed':'open'} · attached ${t.measured.attached_sensor?'yes':'no'}</p>${table(['xyz / grip','Prediction','Command đã gửi','Response đo'],[0,1,2].map((j)=>[['x (m)','y (m)','z (m)'][j],fmt(t.predicted_action[j]),fmt(t.sent_command[j]),fmt(t.measured.ee[j])]).concat([['grip',fmt(t.predicted_action[3]),fmt(t.sent_command[3]),t.measured.grip_closed?'closed':'open']]))}<p>Outcome episode: <strong>${ep.success?'PASS':'FAIL / TIMEOUT'}</strong>${kind==='unknown'?' · sensor verifier deliberately withheld':''}. Feature35 không là VLM latent.</p>`;
 root.querySelector('#eng-stages').innerHTML=Object.entries(t.score).map(([k,v])=>`<span class="eng-stage ${v}"><strong>${labels[k]}</strong>${({pass:'Pass',fail:'Fail ở cuối lượt',in_progress:'Đang thử',unknown:'Chưa rõ',not_attempted:'Chưa thử'})[v]}</span>`).join('');root.querySelector('#eng-raw').textContent=JSON.stringify(t,null,2);}
 function tick(){if(signal.aborted||!playing)return;const n=bundle.cases[kind].trace.length;if(index>=n-1){stop();return;}index++;render();timer=setTimeout(tick,80);}
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.engStep!==undefined){step=Number(b.dataset.engStep);workflow();return;}if(b.id==='eng-play'){if(playing){stop();return;}if(index===bundle.cases[kind].trace.length-1)index=0;playing=true;play.textContent='Ⅱ Tạm dừng';play.setAttribute('aria-pressed','true');tick();}if(b.id==='eng-end'){stop();index=bundle.cases[kind].trace.length-1;render();}},{signal});
 root.querySelector('#eng-case').addEventListener('change',e=>{stop();kind=e.target.value;index=0;render();},{signal});range.addEventListener('input',()=>{stop();index=Number(range.value);render();},{signal});
 play.disabled=false;range.disabled=false;root.querySelector('#eng-end').disabled=false;root.querySelector('#eng-load-status').textContent=`Run ${r.measured_at_utc} · ${bundle.validation.passed} reference tests passed · artifact hashes và source trong manifest.`;
 workflow();summary();render();
 }catch(e){if(signal.aborted)return;root.querySelector('#eng-load-status').textContent='Không đọc được artifacts: '+e.message+'. Mở Report/Manifest để kiểm dữ liệu; không giả lập kết quả.';root.querySelector('#eng-workflow').innerHTML='<p>Replay chưa tải được. Các raw artifacts được liên kết ở dưới.</p>';}
}

const NATIVE_WALKTHROUGH=[
 ['Task và binding','Khóa task trước khi chọn dữ liệu','“Lấy linh kiện vàng, đặt vào A1, nhả và rút tay.” Khóa camera/state/action/controller, vùng thao tác và tiêu chuẩn toàn task. GR1 một tay/torso cố định cần binding thật; chưa coi config29D là đã đáp ứng task.', 'TaskSpec + BindingManifest + acceptance; native còn cần kiểm.', 'task-start.png'],
 ['Dữ liệu','Mỗi nguồn có nhãn và vai trò riêng','Robot seed/correction có observations/state/actions. Human RGB có tracking chỉ vào motion objective khi có geometry/bridge hợp lệ. Synthetic execution phải chạy trong sim và ghi outcome. Human-motion chưa là robot joint target.', 'Dataset releases + rights + provenance + masks/roots.', 'human-demo.png'],
 ['QA và splits','Từ chối dữ liệu sai trước training','Split roots/scenarios trước variants. Kiểm frame/time/action semantics/normalization. Human thiếu pose không zero-fill; failed action không positive label. Final giữ riêng khỏi sinh dữ liệu và correction.', 'QA receipt + frozen train/development/final manifests.', 'task-start.png'],
 ['Training','Loss nối đúng tới modules được cập nhật','Native action objective theo selected head; VLM/action expert có thể nhận gradient qua đường được mở. Human objective có route riêng; shared motor là hypothesis. Kiểm trainable/frozen params, masks, actual updates và checkpoint/reload.', 'TrainingPlan + GradientManifest + train receipt + checkpoint.', 'task-start.png'],
 ['Inference','Theo dõi từ representation tới robot','Processed image/instruction → VLM features/masks → action expert cùng robot state/ID → normalized chunk → denormalization/scheduler/controller → measured response. Scorer dùng state để chấm, không đưa privilege vào image policy ngầm.', 'Input / feature / action / command / response traces; native chưa thu.', 'task-start.png'],
 ['Lỗi và evidence','Ví dụ: gắp được nhưng rơi lúc chuyển','Chấm first divergence; lỗi chuyển có thể từ pose gắp. So prediction, command và response trước thiếu-data hypothesis. Probe representation cần labels/controls; tensor hoặc text explanation chưa chỉ ra nguyên nhân.', 'EvidenceCard: facts / hypotheses / alternatives / next tests.', 'contact-failure.png'],
 ['Can thiệp','Kỹ sư chọn một thử nghiệm có lý do','Binding/controller sai thì repair và re-pin baseline. Coverage hypothesis thì chọn targeted correction hoặc source phù hợp; human/sim chỉ sau gate. Action-only/vision/interface update scope là thử nghiệm riêng, không suy từ fail-rate.', 'InterventionPlan + reviewer + dataset/compute cap.', 'contact-failure.png'],
 ['Học và kiểm lại','Giữ prior data, kiểm cả chuỗi','Dữ liệu mới qua QA, giữ context và authority, replay dữ liệu cũ. Candidate dùng recipe/modules đã khai. Đo lại task từ đầu, transitions và conditions đang tốt; local success không đủ để chọn phiên bản.', 'New checkpoint + full-task/regression results + all failures.', 'task-success.png'],
 ['Final và bàn giao','Bàn giao khi có artifact đúng scope','Freeze recipe/checkpoint/binding/scorer rồi kiểm final độc lập. Đạt quality mới so robot roots và total cost. Chưa đủ bằng chứng thì not-tested/no-gain; sim pass chưa nghiệm thu robot thật.', 'SkillBundle + SOP + QualityCostReport; native chưa có kết quả.', 'task-success.png']
];
function engineeringNativeWalkthrough(){return `<section class="panel eng-native-story"><span class="eyebrow">EXAMPLE SOLUTION XUYÊN SUỐT · CÁCH TRIỂN KHAI NATIVE</span><h2>Từ lệnh “đặt vào A1” đến một skill được kiểm chứng</h2><p>Đi từng bước để thấy input, xử lý và artifact phải có. Các ảnh là minh họa AI; chưa bản ghi GR1. Phần đã thực thi được kiểm riêng ở phụ lục, không thay native proof.</p><div class="eng-native-nav" role="group" aria-label="Workflow native">${NATIVE_WALKTHROUGH.map((x,i)=>`<button type="button" data-native-step="${i}" aria-pressed="${i===0}">${i+1}. ${x[0]}</button>`).join('')}</div><div id="native-walkthrough-detail"></div></section>`;}
function initNativeWalkthrough(signal){const root=document.querySelector('.eng-native-story');if(!root)return;function show(i){const x=NATIVE_WALKTHROUGH[i];root.querySelector('#native-walkthrough-detail').innerHTML=`<div class="eng-native-detail"><figure><img src="assets/story/${x[4]}" alt="Minh họa AI cho workflow ${esc(x[0])}; không native rollout" width="1672" height="941"><figcaption>Ảnh minh họa AI · Chưa native GR1 rollout</figcaption></figure><div><span class="eyebrow">BƯỚC ${i+1}/9</span><h3>${x[1]}</h3><p>${x[2]}</p><div class="eng-native-output"><strong>Output / bằng chứng bắt buộc</strong><p>${x[3]}</p></div></div></div>`;root.querySelectorAll('[data-native-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.nativeStep)===i)));}root.addEventListener('click',e=>{const b=e.target.closest('[data-native-step]');if(b)show(Number(b.dataset.nativeStep));},{signal});show(0);}
